export function slugify(input: string): string {
  return input
    .toLowerCase()
    .replace(/[^\p{L}\p{N}]+/gu, "-")
    .replace(/^-+|-+$/gu, "");
}

better.tests/slugify.test.ts:
import { test } from "node:test";
import assert from "node:assert/strict";
import { slugify } from "../src/slugify.ts";

test("lowercases and joins words with a single dash", () => {
  assert.equal(slugify("Hello World"), "hello-world");
});

test("collapses a run of punctuation into one dash", () => {
  assert.equal(slugify("a -- b"), "a-b");
});

test("strips leading and trailing dashes", () => {
  assert.equal(slugify("!!hello!!"), "hello");
});

test("keeps digits", () => {
  assert.equal(slugify("Part 2"), "part-2");
});

test("an input of only punctuation becomes the empty string", () => {
  assert.equal(slugify("!!!"), "");
});

