worse.tests/slugify.test.ts:
import { test } from "node:test";
import assert from "node:assert/strict";
import { slugify } from "../src/slugify.ts";

test("slugify works", () => {
  slugify("Hello World");
  assert.ok(true);
});

test("slugify does not throw", () => {
  assert.doesNotThrow(() => slugify("!!hello!!"));
});

test("slugify returns a string", () => {
  assert.equal(typeof slugify("Part 2"), "string");
});
